import { existsSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { DatabaseSync } from "node:sqlite";
import { Effect } from "effect";
import { deriveServerPaths } from "../../config.ts";
import { acquireDatabaseLifecycleLock, releaseDatabaseLifecycleLock } from "../DatabaseLifecycleLock.ts";

export function makeSqlitePersistenceLive(root: string) {
  const databasePath = deriveServerPaths(root, null).dbPath;
  if (existsSync("state.sqlite") || existsSync("state.sqlite-wal") || existsSync("state.sqlite-shm")) {
    throw new Error("PREBASELINE_RESET_REQUIRED");
  }
  mkdirSync(dirname(databasePath), { recursive: true });
  return Effect.acquireRelease(
    acquireDatabaseLifecycleLock(databasePath),
    (lock) => releaseDatabaseLifecycleLock(lock),
  ).pipe(Effect.flatMap(() => Effect.sync(() => {
    if (existsSync("state.sqlite") || existsSync("state.sqlite-wal") || existsSync("state.sqlite-shm")) {
      throw new Error("PREBASELINE_RESET_REQUIRED");
    }
    const database = new DatabaseSync(databasePath);
    database.exec("CREATE TABLE automation_meta(schema_generation INTEGER)");
    database.close();
  })));
}
